UNPIVOT (
  SELECT antiBias.correctOptionIndexCounts.*
  FROM read_json_auto('output/audits/ielts-reading-rights-multiple-choice-2026-08-09/validation.json')
) ON A, B, C, D INTO NAME position VALUE count;

SELECT verdict.*
FROM read_json_auto('output/audits/ielts-reading-rights-multiple-choice-2026-08-09/audit-verdicts.json') AS audit,
UNNEST(audit.rows) AS rows(verdict);

